278	SIGNAL structure ordered_workflow {
279	  description: "Prompts with ordered workflow markers that imply phased execution."
280	  feature: { source: { sequences: [["first", "then"], ["first", "next", "finally"], ["先", "再"], ["首先", "然后"]], type: "sequence" }, type: "sequence" }
