317	SIGNAL complexity general_reasoning {
318	  threshold: 0.14
319	  description: "General difficulty boundary for simple answers versus synthesis-heavy reasoning."
320	  hard: { candidates: ["compare several approaches and justify the trade-offs", "build a rigorous step-by-step argument", "synthesize constraints into a plan", "root-cause analysis for a complex failure", "derive the answer from first principles", "严格论证并比较取舍"] }
321	  easy: { candidates: ["brief definition", "quick summary", "simple explanation", "short direct answer", "rewrite this sentence", "简单解释一下"] }
322	}
323	
324	SIGNAL complexity code_task {
325	  threshold: 0.12
326	  description: "Coding and software-engineering difficulty for cheap code help versus hard systems work."
327	  composer: { operator: "AND", conditions: [{ type: "domain", name: "computer science" }] }
328	  hard: { candidates: ["design a distributed system with failure handling", "debug a race condition in production", "optimize a database query plan at scale", "refactor a large service boundary safely", "migrate a monolith to microservices"] }
329	  easy: { candidates: ["explain what this function does", "fix a small bug in this code snippet", "write a helper function", "convert this loop to a list comprehension", "explain the stack trace briefly"] }
330	}
331	
332	SIGNAL complexity math_task {
333	  threshold: 0.12
334	  description: "Math difficulty for simple calculations versus formal proofs and derivations."
335	  composer: { operator: "AND", conditions: [{ type: "domain", name: "math" }] }
336	  hard: { candidates: ["prove the theorem rigorously", "derive the equation step by step", "analyze asymptotic behavior formally", "solve a differential equation with proof", "prove this by contradiction"] }
337	  easy: { candidates: ["what is 2 plus 2", "solve this simple linear equation", "calculate a percentage", "basic geometry area question", "simple arithmetic word problem"] }
338	}
