343	  composer: { operator: "AND", conditions: [{ type: "domain", name: "law" }] }
344	  hard: { candidates: ["analyze indemnity, liability, and jurisdiction risk", "compare two compliance strategies and regulatory exposure", "draft a legal-risk memo for cross-border operations", "interpret contract clauses with risk trade-offs"] }
345	  easy: { candidates: ["what does NDA mean", "define arbitration clause", "explain what compliance means", "brief overview of a privacy policy"] }
346	}
347	
348	SIGNAL complexity agentic_delivery {
349	  threshold: 0.12
350	  description: "Workflow and execution difficulty boundary for agentic requests."
351	  hard: { candidates: ["create a migration plan with checkpoints, rollback, and validation", "troubleshoot this production issue until the root cause is fixed", "design an execution workflow with milestones, owners, and guardrails", "automate the process and include verification after each phase", "break this project into tasks, dependencies, and acceptance checks"] }
352	  easy: { candidates: ["give me a short checklist", "provide a simple one-step setup guide", "write a small implementation plan", "suggest the next step only", "give me a brief task list"] }
353	}
354	
355	SIGNAL complexity evidence_synthesis {
356	  threshold: 0.12
357	  description: "Evidence-heavy research boundary for source-backed synthesis versus lighter overview tasks."
358	  composer: { operator: "OR", conditions: [{ type: "domain", name: "business" }, { type: "domain", name: "economics" }, { type: "domain", name: "health" }, { type: "domain", name: "history" }, { type: "domain", name: "law" }, { type: "domain", name: "philosophy" }, { type: "domain", name: "psychology" }] }
359	  hard: { candidates: ["compare several sources and recommend the strongest evidence-backed position", "write a source-backed memo that synthesizes multiple references", "survey the literature and explain conflicting evidence with citations", "compare policy or historical interpretations and justify the conclusion", "synthesize several studies into one decision recommendation"] }
360	  easy: { candidates: ["give a quick overview of the topic", "summarize one article briefly", "explain the term in simple language", "list the main idea without detailed sourcing", "provide a short summary only"] }
361	}
