363	PROJECTION partition balance_domain_partition {
364	  semantics: "softmax_exclusive"
365	  temperature: 0.1
366	  members: ["biology", "business", "chemistry", "computer science", "economics", "engineering", "health", "history", "law", "math", "other", "philosophy", "physics", "psychology"]
367	  default: "other"
368	}
