370	PROJECTION partition balance_intent_partition {
371	  semantics: "softmax_exclusive"
372	  temperature: 0.18
373	  members: ["agentic_workflows", "architecture_design", "business_analysis", "code_general", "complex_stem", "creative_tasks", "fast_qa_en", "fast_qa_zh", "general_chat_fallback", "health_guidance", "history_explainer", "premium_legal_analysis", "psychology_support", "reasoning_general_en", "reasoning_general_zh", "research_synthesis"]
374	  default: "general_chat_fallback"
375	}
